import Home from "./pages/Home";
import { createTheme, MantineProvider } from '@mantine/core';

import { Button } from "@mantine/core";

const theme = createTheme({
  primaryColor: 'blue',
});

function App() {
  return (
    <MantineProvider
      theme={theme}
    >
      <Button variant="outline" color="blue" size="md">
        Menu
      </Button>
      <Home />
    </MantineProvider>
  )
}

export default App;
